class Solution {
public:
    int minTime(string s, vector<int>& order, int k) {
        int n = s.size();
        long long total = 1LL * n * (n + 1) / 2;
        vector<int> left(n), right(n);
        iota(left.begin(), left.end(), 0);
        iota(right.begin(), right.end(), 0);
        vector<bool> star(n, false);
        long long rem = total;
        for (int t = 0; t < n; t++) {
            int i = order[t], l = left[i], r = right[i];
            rem -= 1LL * (r - l + 1) * (r - l + 2) / 2;
            if (i > l) rem += 1LL * (i - l) * (i - l + 1) / 2;
            if (r > i) rem += 1LL * (r - i) * (r - i + 1) / 2;
            star[i] = true;
            if (i > 0 && !star[i - 1]) right[left[i - 1]] = i - 1;
            if (i + 1 < n && !star[i + 1]) left[right[i + 1]] = i + 1;
            if (total - rem >= k) return t;
        }
        return -1;
    }
};

