class Solution {
public:
    int minTime(string s, vector<int>& order, int k) {
        int n = s.size();
        long long total = 1LL * n * (n + 1) / 2;
        auto ok = [&](int t) {
            vector<bool> star(n, false);
            for (int i = 0; i <= t; i++) star[order[i]] = true;
            long long rem = 0; int run = 0;
            for (int i = 0; i < n; i++) { run = star[i] ? 0 : run + 1; rem += run; }
            return total - rem >= k;
        };
        int lo = 0, hi = n - 1, ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (ok(mid)) { ans = mid; hi = mid - 1; } else lo = mid + 1;
        }
        return ans;
    }
};

